[
  {
    "text": "In a temporal prediction task, models that update internal state without spatialized time features will yield lower prediction error on time intervals not present in the training set than models given explicit time encodings.",
    "topic": "Empirical prediction"
  },
  {
    "text": "The advantage of implicit over explicit time representations increases with the degree of non-stationarity in the data-generating process.",
    "topic": "Non-stationarity"
  },
  {
    "text": "Explicit time features lead to representations that are specific to observed time steps, impairing generalization when temporal patterns shift.",
    "topic": "Overfitting mechanism"
  },
  {
    "text": "A valid benchmark for this hypothesis must compute held-out performance on future time windows, not merely on randomly held-out instances.",
    "topic": "Validation protocol"
  }
]
